window.ScripturaLexicons.DGP.entriesHtml += "<article id=\"entry-dgp-7801\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράχιστος</h1><div class=\"entry-meta\"><span>DGP · ordem 597 na letra β · nº geral 7801</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">superl. poét. de βραχύς.</p></section></article>\n<article id=\"entry-dgp-7802\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχίων, ονος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 598 na letra β · nº geral 7802</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 braço 2 espádua dos animais 3 poét. força.</p></section></article>\n<article id=\"entry-dgp-7803\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράχος, εος-ους(τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 599 na letra β · nº geral 7803</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pl. βράχεα, contr. βράχη) escória.</p></section></article>\n<article id=\"entry-dgp-7804\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύβιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 600 na letra β · nº geral 7804</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vive por pouco tempo. 〈βραχύς, βίος〉</p></section></article>\n<article id=\"entry-dgp-7805\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύκωλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 601 na letra β · nº geral 7805</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de membros curtos. 〈βραχύς, κῶλος〉</p></section></article>\n<article id=\"entry-dgp-7806\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχυλογέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 602 na letra β · nº geral 7806</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">falar com brevidade. 〈βραχυλόγος〉</p></section></article>\n<article id=\"entry-dgp-7807\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχυλογία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 603 na letra β · nº geral 7807</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">concisão. 〈βραχυλόγος〉</p></section></article>\n<article id=\"entry-dgp-7808\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύλογος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 604 na letra β · nº geral 7808</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que se expressa de modo conciso; conciso; lacônico. 〈βραχύς, λέγω〉</p></section></article>\n<article id=\"entry-dgp-7809\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύνω</h1><div class=\"entry-meta\"><span>DGP · ordem 605 na letra β · nº geral 7809</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βραχυνῶ) 1 abreviar; encurtar 2 pronunciar uma sílaba como breve. 〈βραχύς〉</p></section></article>\n<article id=\"entry-dgp-7810\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχυόνειρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 606 na letra β · nº geral 7810</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 com poucos sonhos ou sonhos curtos 2 que é um sonho breve. 〈βραχύς, ὄνειρος〉</p></section></article>\n<article id=\"entry-dgp-7811\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύπορος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 607 na letra β · nº geral 7811</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de curto trajeto 2 de passagem estreita. 〈βραχύς, πόρος〉</p></section></article>\n<article id=\"entry-dgp-7812\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 608 na letra β · nº geral 7812</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. βραχύτερος, poét. βράσσων; superl. βραχύτατος e βράχιστος) 1 curto; pequeno (tamanho): βρ. τεῖχος tuc. muro baixo 2 curto; breve (duração): βραχὺν δὲ βίοτον ἐμπνέων eur. um breve sopro de vida, βραχεῖαν ἡμέραν παίδων eur. a pouca idade das crianças, ἡ β. προσῳδία artt. a quantidade breve (das vogais), ἐν χρόνῳ βραχεῖ, ἐν βραχυτάτῳ brevemente; rapidamente; muito rapidamente, κατὰ βραχύ pouco a pouco 3 pouco numeroso (quantidade): βραχεῖς ἱππεῖς pol. cavaleiros pouco numerosos, πατρίδα ἕνεκα κέρδους βραχέος προέσθαι dem. sacrificar os interesses da pátria por um ganho insignificante, διὰ βραχυτάτων em poucas palavras 4 pequeno; medíocre; fraco (qualidade): βρ. πρόφασις eur. vão pretexto.</p></section></article>\n<article id=\"entry-dgp-7813\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύστομος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 609 na letra β · nº geral 7813</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de boca estreita. 〈βραχύς, στόμα〉</p></section></article>\n<article id=\"entry-dgp-7814\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχύτης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 610 na letra β · nº geral 7814</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pequenez 2 brevidade 3 fraqueza; insignificância. 〈βραχύς〉</p></section></article>\n<article id=\"entry-dgp-7815\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βραχυχρόνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 611 na letra β · nº geral 7815</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de curta duração; transitório; efêmero ♦ τὸ βραχυχρόνιον 2 curta duração; brevidade. 〈βραχύς, χρόνος〉</p></section></article>\n<article id=\"entry-dgp-7816\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βράχω</h1><div class=\"entry-meta\"><span>DGP · ordem 612 na letra β · nº geral 7816</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor.2 3a sing. ἔβραχε ou βράχε) 1 retinir; ressoar 2 estalar; ranger 3 rar. soltar um grito terrível.</p></section></article>\n<article id=\"entry-dgp-7817\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρεκεκεκέξ</h1><div class=\"entry-meta\"><span>DGP · ordem 613 na letra β · nº geral 7817</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">onomat. do coaxar das rãs, brequequequex.</p></section></article>\n<article id=\"entry-dgp-7818\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρέμω</h1><div class=\"entry-meta\"><span>DGP · ordem 614 na letra β · nº geral 7818</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἔβρεμον) 1 rugir; (mar) bramir; (armas) vibrar com estrépito 2 fazer ressoar (instrumento musical) 3 vociferar algo, ac., contra alguém, dat. ♦ méd. 4 (instrumento musical) ressoar.</p></section></article>\n<article id=\"entry-dgp-7819\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρενθύομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 615 na letra β · nº geral 7819</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf. ἐβρενθύομεν) 1 endireitar-se; tomar uma atitude altiva 2 encolerizar-se; revoltar-se.</p></section></article>\n<article id=\"entry-dgp-7820\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρέτας, εος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 616 na letra β · nº geral 7820</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">estátua antiga de madeira; estátua.</p></section></article>\n<article id=\"entry-dgp-7821\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρέφος, εος-ους (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 617 na letra β · nº geral 7821</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 feto 2 bebê 3 criança: ἐκ βρέφεος, ἀπὸ βρέφους desde criança 4 animal pequeno; filhote.</p></section></article>\n<article id=\"entry-dgp-7822\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρεφύλλιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 618 na letra β · nº geral 7822</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">criança pequena. 〈βρέφος〉</p></section></article>\n<article id=\"entry-dgp-7823\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρεχμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 619 na letra β · nº geral 7823</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parte superior da cabeça 2 pl. os parietais 3 infusão; decocção. 〈βρέχω〉</p></section></article>\n<article id=\"entry-dgp-7824\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρέχω</h1><div class=\"entry-meta\"><span>DGP · ordem 620 na letra β · nº geral 7824</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βρέξω, aor. ἔβρεξα, perf. desus.; pas. fut. βραχήσομαι, aor. ἐβρέχθην, aor.2 ἐβράχην, perf. βέβρεγμαι) 1 molhar; empapar; mergulhar num líquido: ἱδρῶτι πᾶσαν ἔβρεξε τὴν ψυχήν plat. banhou de suor a alma toda 2 fazer chover: ἔβρεξε Κύριος χάλαζαν sept. o Senhor fez chover granizo 3 impes. chover ♦ méd. pas. 4 molhar-se; empapar-se: ἐν ὕδατι βρέχεσθαι her. molhar-se na água, βρεχόμενοι πρὸς τὸν ὀμφαλόν xen. molhados até o umbigo, ἀκτῖσι βεβρεγμένος pínd. banhado de luz, γῆ βρεχομένη sept. terra inundada 5 embriagar-se: μέθῃ βρεχθείς eur. ébrio 6 tomar chuva: τὸ ἄγαλμα οὐ βρέχεται pol. a estátua não toma chuva.</p></section></article>\n<article id=\"entry-dgp-7825\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βριάρεως, εω (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 621 na letra β · nº geral 7825</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Briareu, gigante de cem braços, defensor dos deuses contra os Titãs; Βριάρεω στῆλαι colunas de Briareu, ant. n. das colunas de Héracles; ὁ γεωμετρικὸς Βρ. o Briareu da geometria, epít. de Arqui­medes. 〈βριαρός〉</p></section></article>\n<article id=\"entry-dgp-7826\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριαρός, ά, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 622 na letra β · nº geral 7826</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">forte; sólido.</p></section></article>\n<article id=\"entry-dgp-7827\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 623 na letra β · nº geral 7827</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e aor. ἔβριξα) 1 estar sonolento 2 estar pesado; estar entorpecido. 〈βρίθω〉</p></section></article>\n<article id=\"entry-dgp-7828\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριήπυος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 624 na letra β · nº geral 7828</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de grito terrível. 〈βρι-, ἠπύω〉</p></section></article>\n<article id=\"entry-dgp-7829\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρίθῃσι</h1><div class=\"entry-meta\"><span>DGP · ordem 625 na letra β · nº geral 7829</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">3a sing. pres. subj. ép. de βρίθω.</p></section></article>\n<article id=\"entry-dgp-7830\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριθοσύνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 626 na letra β · nº geral 7830</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">peso; gravidade. 〈βρίθω〉</p></section></article>\n<article id=\"entry-dgp-7831\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριθύς, εῖα, ύ</h1><div class=\"entry-meta\"><span>DGP · ordem 627 na letra β · nº geral 7831</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">pesado; grave.</p></section></article>\n<article id=\"entry-dgp-7832\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρίθω</h1><div class=\"entry-meta\"><span>DGP · ordem 628 na letra β · nº geral 7832</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βρίσω, aor. ἔβρισα, perf. βέβριθα; pas. só pres.) 1 estar pesado; ter peso; superar: β. εὐδοξίᾳ pínd. ter peso, ser poderoso pela reputação, β. ἐέδνοισι hom. prevalecer pelos presentes 2 carregar; encher: β. τάλαντα ésql. encher os pratos da balança, β. τινὰ πλούτῳ pínd. cumular alguém de riqueza 3 estar carregado ou cheio de; estar sob o peso de, dat. ou gen.: [ναῦς] βεβρίθει σάκεσι καὶ ἔγκεσσιν hom. o navio está carregado de escudos e de lanças, τράπεζαι σίτου καὶ κρειῶν ἠδ’ οἴνου βεβρίθασι hom. as mesas estão cheias de pão, carne e vinho.</p></section></article>\n<article id=\"entry-dgp-7833\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριμάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 629 na letra β · nº geral 7833</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rugir de cólera.</p></section></article>\n<article id=\"entry-dgp-7834\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βριμόομαι-οῦμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 630 na letra β · nº geral 7834</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só impf. 3ª sing. ἐβριμοῦτο) indignar-se contra alguém, dat. 〈βρίθω〉</p></section></article>\n<article id=\"entry-dgp-7835\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρομέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 631 na letra β · nº geral 7835</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres. e impf.) fremir; zumbir; ressoar. 〈βρόμος〉</p></section></article>\n<article id=\"entry-dgp-7836\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βρόμιος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 632 na letra β · nº geral 7836</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquele que brame; aquele que ressoa 2 aquele que faz estremecer; aquele que provoca tremor sagrado; Brômio, epít. de Dioniso; Βρομίου πῶμα eur. a bebida de Brômio, vinho 3 vinho. 〈βρόμος〉</p></section></article>\n<article id=\"entry-dgp-7837\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρόμος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 633 na letra β · nº geral 7837</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">frêmito; ribombo; estalo. 〈βρέμω〉</p></section></article>\n<article id=\"entry-dgp-7838\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροντάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 634 na letra β · nº geral 7838</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βροντήσω) 1 trovejar ♦ pas. 2 ser atin­gido por raio. 〈βροντή〉</p></section></article>\n<article id=\"entry-dgp-7839\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροντή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 635 na letra β · nº geral 7839</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 trovão; barulho do trovão 2 rar. estado daquele que foi atingido pelo raio; estupor. 〈βρέμω〉</p></section></article>\n<article id=\"entry-dgp-7840\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρόντημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 636 na letra β · nº geral 7840</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">trovoada. 〈βροντάω〉</p></section></article>\n<article id=\"entry-dgp-7841\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρότειος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 637 na letra β · nº geral 7841</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e α, ον = βρότεος.</p></section></article>\n<article id=\"entry-dgp-7842\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρότεος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 638 na letra β · nº geral 7842</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de mortais; mortal; humano. 〈βροτός〉</p></section></article>\n<article id=\"entry-dgp-7843\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτόεις, όεσσα, όεν</h1><div class=\"entry-meta\"><span>DGP · ordem 639 na letra β · nº geral 7843</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">coberto de sangue; ensangüentado. 〈βροτός〉</p></section></article>\n<article id=\"entry-dgp-7844\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτοκτονέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 640 na letra β · nº geral 7844</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. pres.) matar um homem. 〈βρο­τός, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-7845\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτοκτόνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 641 na letra β · nº geral 7845</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">homicida; assassino. 〈βροτός, κτείνω〉</p></section></article>\n<article id=\"entry-dgp-7846\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτολοιγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 642 na letra β · nº geral 7846</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">funesto para os mortais. 〈βροτός, λοιγός〉</p></section></article>\n<article id=\"entry-dgp-7847\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 643 na letra β · nº geral 7847</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mortal 2 duv. morto ♦ ὁ, ἡ βροτός 3 o mortal; a mortal.</p></section></article>\n<article id=\"entry-dgp-7848\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρότος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 644 na letra β · nº geral 7848</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">sangue que escorre de um ferimento; fluxo sanguíneo.</p></section></article>\n<article id=\"entry-dgp-7849\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτοσκόπος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 645 na letra β · nº geral 7849</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que vigia os mortais. 〈βροτός, σκέπ­τομαι〉</p></section></article>\n<article id=\"entry-dgp-7850\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτοστυγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 646 na letra β · nº geral 7850</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">odioso para os mortais. 〈βροτός, στυγέω〉</p></section></article>\n<article id=\"entry-dgp-7851\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτοφθόρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 647 na letra β · nº geral 7851</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que faz perecer os mortais. 〈βροτός, φθείρω〉</p></section></article>\n<article id=\"entry-dgp-7852\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βροτόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 648 na letra β · nº geral 7852</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só part. perf. pas. βεβροτωμένα) sujar de sangue. 〈βρότος〉</p></section></article>\n<article id=\"entry-dgp-7853\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρόχος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 649 na letra β · nº geral 7853</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 cordão; corda para estrangular ou enforcar. 2 malha de rede; rede de caça.</p></section></article>\n<article id=\"entry-dgp-7854\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρυάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 650 na letra β · nº geral 7854</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 encher-se; estar farto; inchar-se. 2 inchar-se de orgulho; regozijar-se. 〈βρύω〉</p></section></article>\n<article id=\"entry-dgp-7855\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρυασμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 651 na letra β · nº geral 7855</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">volúpia. 〈βρυάζω〉</p></section></article>\n<article id=\"entry-dgp-7856\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρυγμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 652 na letra β · nº geral 7856</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mordida 2 o ranger de dentes 3 bíbl. grunhido. 〈βρύχω〉</p></section></article>\n<article id=\"entry-dgp-7857\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύκω</h1><div class=\"entry-meta\"><span>DGP · ordem 653 na letra β · nº geral 7857</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. βρύξω, aor. ἔβρυξα, perf. desus.) 1 morder 2 comer avidamente; consumir até o fim; devorar ♦ at. e méd. 3 ranger os dentes.</p></section></article>\n<article id=\"entry-dgp-7858\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 654 na letra β · nº geral 7858</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 vegetação parasita (musgo; líquen) 2 amentilho do salgueiro, do choupo. 〈βρύω〉</p></section></article>\n<article id=\"entry-dgp-7859\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρυχάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 655 na letra β · nº geral 7859</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. desus., aor. ἐβρυχήθην, aor. méd. ἐβρυχησάμην; perf. βέβρυχα com sent. de pres.) rugir; mugir; barrir.</p></section></article>\n<article id=\"entry-dgp-7860\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύχημα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 656 na letra β · nº geral 7860</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">rugido. 〈βρυχάομαι〉</p></section></article>\n<article id=\"entry-dgp-7861\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύχιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 657 na letra β · nº geral 7861</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον do fundo; que está no fundo do mar ou da terra.</p></section></article>\n<article id=\"entry-dgp-7862\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύχω</h1><div class=\"entry-meta\"><span>DGP · ordem 658 na letra β · nº geral 7862</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">βρύκω.</p></section></article>\n<article id=\"entry-dgp-7863\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρύω</h1><div class=\"entry-meta\"><span>DGP · ordem 659 na letra β · nº geral 7863</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., impf. ἔβρυον e fut. βρύσω) 1 cobrir-se de; abundar em, dat. ou gen. 2 brotar vigorosamente: ἡ γῆ βρύει xen. a terra se cobre de vegetação, βρ. μελίτταις καὶ προβάτοις ar. regurgitar de abelhas e ovelhas 3 fazer brotar; fazer florir (campinas, rosas).</p></section></article>\n<article id=\"entry-dgp-7864\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρυώδης, ης, ες</h1><div class=\"entry-meta\"><span>DGP · ordem 660 na letra β · nº geral 7864</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coberto de espuma; coberto de musgo 2 semelhante a um amentilho. 〈βρύον〉</p></section></article>\n<article id=\"entry-dgp-7865\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωθήσομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 661 na letra β · nº geral 7865</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. βιβρώσκω.</p></section></article>\n<article id=\"entry-dgp-7866\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρῶμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 662 na letra β · nº geral 7866</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 aquilo que é comestível; alimento; refeição 2 aquilo que é corroído; cárie; úlcera 3 ação de devorar. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7867\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωμάομαι-ῶμαι</h1><div class=\"entry-meta\"><span>DGP · ordem 663 na letra β · nº geral 7867</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zurrar; bramir; barrir.</p></section></article>\n<article id=\"entry-dgp-7868\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρώμη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 664 na letra β · nº geral 7868</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">alimento. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7869\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρώμησις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 665 na letra β · nº geral 7869</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">zurro. 〈βρωμάομαι〉</p></section></article>\n<article id=\"entry-dgp-7870\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρώξω</h1><div class=\"entry-meta\"><span>DGP · ordem 666 na letra β · nº geral 7870</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">fut. rar. de βιβρώσκω.</p></section></article>\n<article id=\"entry-dgp-7871\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρώσιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 667 na letra β · nº geral 7871</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">comestível. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7872\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρῶσις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 668 na letra β · nº geral 7872</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 alimento; pasto 2 ação de comer 3 gosto; sabor 4 corrosão; erosão; ferrugem. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7873\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωτήρ, ῆρος</h1><div class=\"entry-meta\"><span>DGP · ordem 669 na letra β · nº geral 7873</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 comilão; devorador ♦ ὁ βρωτήρ tard. 2 traça. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7874\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 670 na letra β · nº geral 7874</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 voraz 2 corrosivo. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7875\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωτός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 671 na letra β · nº geral 7875</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 comestível ♦ τὸ βρωτόν 2 alimento. 〈βι­βρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7876\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βρωτύς, ύος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 672 na letra β · nº geral 7876</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ação de comer. 〈βιβρώσκω〉</p></section></article>\n<article id=\"entry-dgp-7877\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύας, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 673 na letra β · nº geral 7877</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mocho.</p></section></article>\n<article id=\"entry-dgp-7878\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύβλινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 674 na letra β · nº geral 7878</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de papiro. 〈βύβλoς〉</p></section></article>\n<article id=\"entry-dgp-7879\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύβλος, ου (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 675 na letra β · nº geral 7879</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 papiro 2 pele de papiro; casca 3 folha de papiro 4 rolo de papiro, livro; divisão de um livro 5 as Sagradas Escrituras; a Bíblia.</p></section></article>\n<article id=\"entry-dgp-7880\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βυζάντιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 676 na letra β · nº geral 7880</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Bizâncio, cidade da Trácia, no Bósforo.</p></section></article>\n<article id=\"entry-dgp-7881\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Βυζάντιος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 677 na letra β · nº geral 7881</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de Bizâncio; bizantino.</p></section></article>\n<article id=\"entry-dgp-7882\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύζην</h1><div class=\"entry-meta\"><span>DGP · ordem 678 na letra β · nº geral 7882</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de modo apertado; estreitamente 2 aos montes; em massa. 〈βύω〉</p></section></article>\n<article id=\"entry-dgp-7883\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύζω</h1><div class=\"entry-meta\"><span>DGP · ordem 679 na letra β · nº geral 7883</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só aor. 3asing. ἔβυξε) (o mocho) emitir um grito. 〈βύας〉</p></section></article>\n<article id=\"entry-dgp-7884\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυθίζω</h1><div class=\"entry-meta\"><span>DGP · ordem 680 na letra β · nº geral 7884</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἐβύθισα; part. perf. pas. βεβιθισμένος) imergir até o fundo; afundar. 〈βυθός〉</p></section></article>\n<article id=\"entry-dgp-7885\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύθιος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 681 na letra β · nº geral 7885</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 profundo 2 que se acha no fundo da água; aquático. 〈βυθός〉</p></section></article>\n<article id=\"entry-dgp-7886\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυθός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 682 na letra β · nº geral 7886</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">profundeza; fundo: ὁ βυθὸς [θαλάττης] o fundo do mar, β. ἀθεότητος plut. profundeza ou abismo de impiedade, β. ἀτεχνίης hipócr. o cúmulo da imperícia.</p></section></article>\n<article id=\"entry-dgp-7887\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύκτης, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 683 na letra β · nº geral 7887</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) 1 que zune: βυκτάων ἀνέμων hom. ventos uivantes ♦ ὁ βύκτης 2 vendaval. 〈βύζω〉</p></section></article>\n<article id=\"entry-dgp-7888\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύρσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 684 na letra β · nº geral 7888</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 pele curtida; couro 2 odre para vinho 3 pe­le de animal vivo.</p></section></article>\n<article id=\"entry-dgp-7889\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυρσεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 685 na letra β · nº geral 7889</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">tard. curtidor. 〈βύρσα〉</p></section></article>\n<article id=\"entry-dgp-7890\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυρσοδεψέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 686 na letra β · nº geral 7890</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">preparar o couro. 〈βύρσα, δέψω〉</p></section></article>\n<article id=\"entry-dgp-7891\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυρσοπαγής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 687 na letra β · nº geral 7891</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de pele. 〈βύρσα, πήγνυμι〉</p></section></article>\n<article id=\"entry-dgp-7892\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύσσινος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 688 na letra β · nº geral 7892</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">feito de linho fino. 〈βύσσος〉</p></section></article>\n<article id=\"entry-dgp-7893\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυσσοδομεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 689 na letra β · nº geral 7893</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">construir no fundo (de si mesmo); β. κακά hom. maquinar secretamente maldades, β. ὀργήν luc. nutrir ressentimento no coração. 〈βυσσός, δόμος〉</p></section></article>\n<article id=\"entry-dgp-7894\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυσσόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 690 na letra β · nº geral 7894</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. da profundeza; do fundo. 〈βυσσός〉</p></section></article>\n<article id=\"entry-dgp-7895\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύσσος, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 691 na letra β · nº geral 7895</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bisso, variedade de linho.</p></section></article>\n<article id=\"entry-dgp-7896\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυσσός,</h1><div class=\"entry-meta\"><span>DGP · ordem 692 na letra β · nº geral 7896</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. βυττός, οῦ (ὁ) o fundo do mar.</p></section></article>\n<article id=\"entry-dgp-7897\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυσσόφρων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 693 na letra β · nº geral 7897</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος que guarda os sentimentos no fundo da alma. 〈βυσσός, φρήν〉</p></section></article>\n<article id=\"entry-dgp-7898\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βυττός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 694 na letra β · nº geral 7898</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">át. = βυσσός.</p></section></article>\n<article id=\"entry-dgp-7899\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βύω</h1><div class=\"entry-meta\"><span>DGP · ordem 695 na letra β · nº geral 7899</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres., aor. ἔβυσα; perf. pas. βέβυσμαι e m.-q.-perf. ἐβεβύσμην) 1 encher; guarnecer, gen. ou dat. 2 colocar; ocultar ♦ pas. 3 tornar-se obstruído; estar cheio de, gen. ou dat.: νήματος βεβυσμένος hom. [cesto] cheio de fios, παιδίον κηρίῳ βεβυσμένον ar. um menino com os ouvidos tapados com cera.</p></section></article>\n<article id=\"entry-dgp-7900\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">βῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 696 na letra β · nº geral 7900</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 de βαίνω.</p></section></article>\n";
